function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Sky color

  // Draw the green hills
  brush.fill("#006600"); // Green
  brush.fillBleed(0.5); // Bleed for a soft texture
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Draw the sunset
  brush.fill("#ff4500"); // Orange
  brush.fillBleed(0.3); // Bleed for a soft texture
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Draw the clouds
  brush.fill("#ffffff"); // White
  brush.fillBleed(0.2); // Bleed for a soft texture
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(400, 350);
  brush.vertex(0, 350);
  brush.endShape(true);
}
